-- Origem: Descritores Língua Portuguesa Paebes 2026 1.1.pdf | MATRIZES DE REFERÊNCIA AMA 2026.pdf | MATRIZES DE REFERÊNCIA MT - AMA 2 2026-2.pdf | Matriz referência Ciências Humanas Paebes-PaebesAlfa 2026_9EF_3EM.pdf | Matriz referência Matemática Paebes-PaebesAlfa 2026_2EF_5EF_9EF_3EM.pdf
-- 413 linhas. As 6 sem descricao vem de paginas onde o PDF imprime duas matrizes uma sobre a
-- outra; ficam pelo codigo para o seletor nao mostrar chute.
--
-- Rode supabase/schema.sql antes (a tabela descritores e as politicas dela estao la). Idempotente:
-- roda de novo e atualiza linha por linha pela mesma chave.

-- uma regeneracao que nao pegou o texto nao apaga o que o banco ja tem
on conflict (chave) do update set
  matriz = excluded.matriz,
  codigo = excluded.codigo,
  disciplina = excluded.disciplina,
  componente = excluded.componente,
  ano = excluded.ano,
  banda = excluded.banda,
  descricao = coalesce(nullif(excluded.descricao, ''), public.descritores.descricao),
  fonte = excluded.fonte,
  pagina = excluded.pagina,
  duvidoso = excluded.duvidoso;
